H('260.d.8.C',4,"To keep an audience interested, a presenter might begin with:","A relevant question or story",["An apology","A long list of numbers","Silence"],"Strong openings engage.")
H('260.d.9.A',3,"A marketing-information system collects and organizes data to help with:","Marketing decisions",["Cooking","Exercise","Napping"],"Data supports decisions.")
