H('260.d.12.A',4,"A coupon sent by mail is an example of:","Sales promotion",["Personal selling","Public relations","Product design"],"Coupons promote sales.")
H('260.d.12.B',3,"Visual merchandising for advertising marketing includes attractive:","Displays that draw attention",["Empty shelves","Dark rooms","Blank signs"],"Displays attract buyers.")
