H('260.d.12.C',4,"A campaign set to raise store visits 15% results in 20%. The plan is judged:","Effective for that objective",["Failed","Unmeasurable","Illegal"],"It exceeded the goal.")
H('260.d.13.A',3,"Social media contributes to advertising by allowing:","Direct two-way interaction with consumers",["No interaction","Only print","Only TV"],"Interactive.")
