# ---- 262 Principles of Marketing
H('262.d.1.A',3,"Marketing is the process of creating, communicating, and delivering:","Value to customers",["Taxes","Paperwork","Bank loans"],"Marketing creates value.")
H('262.d.1.A',4,"The marketing concept states that a firm should focus on:","Satisfying customer needs profitably",["Making the cheapest product","Ignoring customers","Hiding costs"],"Customer-centered.")
H('262.d.1.B',3,"Marketing core functions include marketing planning, pricing, promotion, product service management, and:","Distribution",["Taxation","Lawsuits","Payroll"],"Core functions.")
H('262.d.1.B',4,"Gathering customer opinions about a new snack falls under which function?","Marketing-information management",["Financing","Distribution","Purchasing"],"Research function.")
H('262.d.2.A',3,"The four elements of the marketing mix are product, price, place, and:","Promotion",["Profit","Policy","Position"],"Standard four Ps.")
H('262.d.2.A',4,"Where and how a product is made available to customers is the:","Place element",["Price element","Promotion element","Product element"],"Distribution.")
