H('262.d.9.B',3,"A public service announcement on TV is an example of:","Advertising",["Personal selling","Direct sales","Packaging"],"Paid mass message.")
H('262.d.9.B',4,"A sales rep demonstrating a product face to face uses:","Personal selling",["Advertising","Public relations","Branding"],"One-to-one.")
