H('262.d.10.A',4,"A radio ad uses mainly:","Sound and voice",["Images","Print","Packaging"],"Audio only.")
H('262.d.10.B',3,"A press release is a written announcement sent to:","The media",["Competitors only","Employees only","Landlords"],"PR tool.")
H('262.d.10.B',4,"A company sponsoring a charity event is engaging in:","Public relations",["Price cutting","Product design","Stocking"],"Builds goodwill.")
H('262.d.10.C',3,"A coupon is an example of:","Sales promotion",["Public relations","Personal selling","Packaging"],"Short-term incentive.")
